import{_ as a,c as e,o as t,a4 as l}from"./chunks/framework.DzOtv0XR.js";const f=JSON.parse('{"title":"链表","description":"","frontmatter":{},"headers":[],"relativePath":"javascript/data-structures/linked-list.md","filePath":"javascript/data-structures/linked-list.md"}'),r={name:"javascript/data-structures/linked-list.md"},i=l('<h1 id="链表" tabindex="-1">链表 <a class="header-anchor" href="#链表" aria-label="Permalink to &quot;链表&quot;">​</a></h1><nav class="table-of-contents"><ul><li><a href="#基础">基础</a></li><li><a href="#与数组区别">与数组区别</a></li><li><a href="#迭代">迭代</a></li><li><a href="#练习-重考察实现">练习/重考察实现</a></li></ul></nav><h2 id="基础" tabindex="-1">基础 <a class="header-anchor" href="#基础" aria-label="Permalink to &quot;基础&quot;">​</a></h2><p>定义：节点集合，每个节点使用对象引用指向其后继，这个引用叫做链</p><p>线性集合，不按照元素的物理顺序排列，而是每个元素有指向，高效插入和移除通过遍历</p><p>JS 中数组效率低（实现成了对象，与其它语言有别），除了随机访问，都可以用链表替换一维数组</p><p>插入和删除操作展示出高效率，因为只是<strong>调整引用指向</strong></p><p>缺点是访问慢（如随机）</p><p>有哪些操作方法？可以从增删改查来推导</p><p>具有递归特性，题目常用递归解决</p><blockquote><p>前端没有多少实际用途 <a href="https://zhuanlan.zhihu.com/p/61935862" target="_blank" rel="noreferrer">前端应用数据结构：何时使用链表 - 知乎</a></p></blockquote><p>内存连续，指针/引用</p><h2 id="与数组区别" tabindex="-1">与数组区别 <a class="header-anchor" href="#与数组区别" aria-label="Permalink to &quot;与数组区别&quot;">​</a></h2><ul><li>链表-插入删除快 O(1)，随机访问 O(n)</li><li>数组-下标随机访问 O(1)，查找二分 O(log n)</li></ul><h2 id="迭代" tabindex="-1">迭代 <a class="header-anchor" href="#迭代" aria-label="Permalink to &quot;迭代&quot;">​</a></h2><p>cur = cur.next</p><h2 id="练习-重考察实现" tabindex="-1">练习/重考察实现 <a class="header-anchor" href="#练习-重考察实现" aria-label="Permalink to &quot;练习/重考察实现&quot;">​</a></h2><blockquote><p>写起来很容易错，需要考虑很多、多练习，避免易犯错误</p></blockquote><ul><li><p>反转链表 | 交换相邻节点</p></li><li><p>判断是否有环，硬做 1s | set 判重 | 快慢碰撞</p></li><li><p>两个有序的链表合并</p></li><li><p>删除链表倒数第 n 个节点</p></li><li><p>求链表的中间节点</p></li></ul>',19),o=[i];function s(n,p,c,h,d,u){return t(),e("div",null,o)}const b=a(r,[["render",s]]);export{f as __pageData,b as default};
